///  "type": "object",
///  "properties": {
///    "ext": {
///      "description": "Ecosystem-defined extension members per SPEC.md §4.5.1. A host MUST NOT treat a member here as making more records eligible: a removal rule a member's reader cannot understand is one they were never told about.",
///      "$ref": "#/definitions/Ext"
///    },
///    "recordDays": {
///      "description": "Days a record is kept after it last changed, whatever its standing. A record — `active`, `deprecated` or `retracted` — whose `updatedAt` is more than this long ago is eligible, **unless it is pinned**: pinning says what matters in the room, and a room that wants a pinned record gone unpins it first. Absent means records are never eligible by age.",
///      "type": "integer",
///      "maximum": 36500.0,
